    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Talk to High Bear. He will tell you \"I am compiling data on the effects of Bastok's mining and industrial projects on the environment. I've heard adventurers say that the Quadav dumping of industrial waste has polluted Beadeaux and its surrounding areas. I'd like to examine some of that Corrupted Dirt. I've heard you can find some near their forges, and that it's also easier to spot on rainy days.\"",
