        entities = { "High Bear", "Corrupted Dirt" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Go to Beadeaux. Proceed straight in, then turn left (go north) when you reach the wall at F-7. Go north to the wall in F-6, then due east to H-6. From here head south and you'll find yourself going into a cave that leads down. Take that down until it exits at H-7 on the lower map.",
        action = "travel",
        entities = { "Beadeaux" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "F-7", "F-6", "H-6", "H-7" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "From here, go west and south as you can until you come to the tunnel at F-8 that leads back to the surface; you will pass one Afflictor that will Curse you as you proceed. Follow the surface path along, south past the Mute at F-9. Continue south, under the bridge and past the second Afflictor, then head east around the giant smokestacks at G-9/H-9.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "F-8", "F-9", "G-9", "H-9" },
