        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "**",
        depth = 2,
        instruction = "The first, and easiest, set of machines: Go straight in when entering Beadeaux, then turn left (go north) when you reach the wall at F-7. Go north to the wall in F-6, then due east to H-6. From here head south and you'll find yourself going into a cave that leads down. Take that down until it exits at H-7 on the lower map. Go west, south, and west again until... Required details: Beadeaux, F-7, F-6, H-6, H-7, G-8.",
        action = "note",
        entities = { "Beadeaux" },
        zones = {  },
        map_numbers = {  },
