        marker = "*",
        depth = 1,
        instruction = "If someone gets caught, DO NOT press the switch again. This will reset all the switches. Go release the NPC that was captured (via the above mentioned method) and head back to the switch that you previously got wrong and try again. The Guardsmen may or may not be the same one.",
